import DashboardLayout from "@/components/DashboardLayout";
import { AttributeRuleTooltip, SystemRuleTooltip } from "@/components/SystemRuleTooltip";
import { SheetSystemSwitcher } from "@/components/SheetSystemSwitcher";
import { SheetCreationGuide } from "@/components/SheetCreationGuide";
import { QuickRollPanel, type QuickRollOption } from "@/components/QuickRollPanel";
import { CustomArchetypePanel } from "@/components/CustomArchetypePanel";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Button } from "@/components/ui/button";
import { trpc } from "@/lib/trpc";
import { resetInventoryEditorSession } from "@/lib/inventoryEditor";
import { createV5MailtoUrl, createV5PdfFile, downloadV5Pdf, shareV5Pdf } from "@/lib/v5Pdf";
import { V5_ADVANTAGE_DETAILS, V5_ATTRIBUTES, V5_CLANS, V5_DISCIPLINES, V5_DISCIPLINE_ADVANCED_POWERS, V5_FLAW_DETAILS, V5_GENERATIONS, V5_PREDATORS, V5_SKILLS, V5_STARTER_ARCHETYPES, appendV5History, applyClanDisciplines, calculateV5ExperienceCost, createV5SheetData, getV5AdvancementLabel, getV5EquippedArmor, getV5EquippedWeapon, getV5InventoryItems, normalizeV5Inventory, reconcileV5EquipmentAfterInventoryEdit, type V5AdvancementKind, type V5InventoryEntry, type V5SheetData, type V5StarterArchetype, type V5StoreCategory, v5HealthTrack, v5WillpowerTrack } from "@shared/vampire-v5";
import { BadgeCheck, BookOpen, CheckCircle2, ChevronDown, ChevronUp, Crown, Dice6, Download, Droplets, History, LoaderCircle, Mail, PackagePlus, Pencil, Plus, Save, Share2, Shield, ShieldCheck, Sparkles, Trash2, UserRound } from "lucide-react";
import React, { useMemo, useState } from "react";
import { Link } from "wouter";
import { toast } from "sonner";

function hydrateSheet(value: unknown): V5SheetData {
  const base = createV5SheetData();
  const raw = (value || {}) as Partial<V5SheetData>;
  return { ...base, ...raw, attributes: { ...base.attributes, ...(raw.attributes || {}) }, skills: { ...base.skills, ...(raw.skills || {}) }, disciplines: raw.disciplines || {}, advantages: raw.advantages || [], flaws: raw.flaws || [], inventory: normalizeV5Inventory(raw.inventory), experienceHistory: raw.experienceHistory || [], history: raw.history || [] };
}

const inventoryCategories: { value: V5StoreCategory; label: string }[] = [
  { value: "arma", label: "Arma" }, { value: "armadura", label: "Armadura" }, { value: "equipamento", label: "Equipamento" }, { value: "roupa", label: "Vestuário" }, { value: "moradia", label: "Moradia" }, { value: "veiculo", label: "Veículo" }, { value: "montaria", label: "Montaria" },
];

type InventoryDraft = Omit<V5InventoryEntry, "id" | "catalogId" | "source"> & { damageText: string; armorText: string };
const emptyInventoryDraft = (): InventoryDraft => ({ name: "", category: "equipamento", resources: 0, quantity: 1, specification: "", damageText: "", armorText: "" });

function V5SheetContent() {
  const utils = trpc.useUtils();
  const { data: characters = [], isLoading: loadingCharacters, error: charactersError } = trpc.characters.mine.useQuery();
  const { data: campaigns = [], isLoading: loadingCampaigns, error: campaignsError } = trpc.campaigns.mine.useQuery();
  const vampireCharacters = useMemo(() => characters.filter((character) => character.systemId === "vampiro-v5"), [characters]);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [name, setName] = useState("");
  const [concept, setConcept] = useState("");
  const [campaignId, setCampaignId] = useState("");
  const [sheet, setSheet] = useState<V5SheetData>(() => createV5SheetData());
  const [traitName, setTraitName] = useState("");
  const [traitDots, setTraitDots] = useState(1);
  const [flawName, setFlawName] = useState("");
  const [flawDots, setFlawDots] = useState(1);
  const [advancementKind, setAdvancementKind] = useState<V5AdvancementKind>("attribute");
  const [currentDots, setCurrentDots] = useState(1);
  const [targetDots, setTargetDots] = useState(2);
  const [combatResult, setCombatResult] = useState<{ pool: number; dice: number[]; successes: number; damage: number; hungerDice: number; verdict: string; messyCritical: boolean; bestialFailure: boolean } | null>(null);
  const [quickRollResult, setQuickRollResult] = useState<{ label: string; pool: number; dice: number[]; successes: number } | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [inventoryOpen, setInventoryOpen] = useState(true);
  const [inventoryEditorOpen, setInventoryEditorOpen] = useState(false);
  const [editingInventoryId, setEditingInventoryId] = useState<string | null>(null);
  const [inventoryDraft, setInventoryDraft] = useState<InventoryDraft>(emptyInventoryDraft);
  const [lastSavedAt, setLastSavedAt] = useState<Date | null>(null);

  const createCharacter = trpc.characters.create.useMutation({ onSuccess: async (created) => { await utils.characters.mine.invalidate(); setSelectedId(created?.id ?? null); setLastSavedAt(new Date()); toast.success("Ficha V5 autenticada no arquivo."); }, onError: (error) => toast.error(error.message) });
  const updateCharacter = trpc.characters.update.useMutation({ onSuccess: async () => { await utils.characters.mine.invalidate(); setLastSavedAt(new Date()); toast.success("Ficha V5 preservada."); }, onError: (error) => toast.error(error.message) });
  const recordRoll = trpc.characters.recordRoll.useMutation({ onError: (error) => toast.error(error.message) });
  const selectedClan = V5_CLANS.find((clan) => clan.id === sheet.clan);
  const health = v5HealthTrack(sheet.attributes);
  const willpower = v5WillpowerTrack(sheet.attributes);
  const equippedWeapon = getV5EquippedWeapon(sheet);
  const equippedArmor = getV5EquippedArmor(sheet);
  const inventoryItems = getV5InventoryItems(sheet);
  const experienceCost = calculateV5ExperienceCost(advancementKind, currentDots, targetDots);
  const selectedCampaignName = useMemo(() => campaigns.find((campaign) => campaign.id === Number(campaignId))?.title, [campaignId, campaigns]);
  const isSavingSheet = createCharacter.isPending || updateCharacter.isPending;
  const isLoadingArchive = loadingCharacters || loadingCampaigns;
  const archiveError = charactersError || campaignsError;

  const resetInventoryEditor = () => { const reset = resetInventoryEditorSession(); setInventoryEditorOpen(reset.isOpen); setEditingInventoryId(reset.editingId); setInventoryDraft(emptyInventoryDraft()); };
  const openCharacter = (character: typeof vampireCharacters[number]) => { setSelectedId(character.id); setName(character.name); setConcept(character.concept || ""); setCampaignId(character.campaignId ? String(character.campaignId) : ""); setSheet(hydrateSheet(character.sheetData)); resetInventoryEditor(); };
  const newCharacter = () => { setSelectedId(null); setName(""); setConcept(""); setCampaignId(""); setSheet(createV5SheetData()); resetInventoryEditor(); };
  const updateRating = (group: "attributes" | "skills", label: string, change: number) => setSheet((current) => ({ ...current, [group]: { ...current[group], [label]: Math.max(0, Math.min(5, (current[group][label] || 0) + change)) } }));
  const chooseClan = (clanId: string) => { const clan = V5_CLANS.find((item) => item.id === clanId); setSheet((current) => appendV5History({ ...current, clan: clanId, disciplines: clan ? applyClanDisciplines(clanId, current.disciplines) : current.disciplines }, clan ? `Clã definido: ${clan.name}. Disciplinas de origem preparadas.` : "Clã removido.")); };
  const applyStarterArchetype = (archetype: V5StarterArchetype) => { setSheet((current) => appendV5History({ ...current, attributes: { ...current.attributes, ...archetype.attributes }, skills: { ...current.skills, ...archetype.skills } }, `Arquétipo aplicado: ${archetype.label}.`)); toast.success(`Modelo ${archetype.label} aplicado. Revise e ajuste os pontos à sua mesa.`); };
  const applyCustomArchetype = (payload: Record<string, unknown>, title: string) => { const template = payload as Partial<V5SheetData>; setSheet((current) => { const clan = typeof template.clan === "string" ? template.clan : current.clan; const disciplines = clan && clan !== current.clan ? applyClanDisciplines(clan, template.disciplines || {}) : { ...current.disciplines, ...(template.disciplines || {}) }; return appendV5History({ ...current, clan, predator: typeof template.predator === "string" ? template.predator : current.predator, attributes: { ...current.attributes, ...(template.attributes || {}) }, skills: { ...current.skills, ...(template.skills || {}) }, disciplines }, `Arquétipo próprio aplicado: ${title}.`); }); toast.success(`Arquétipo ${title} aplicado à ficha.`); };
  const togglePower = (discipline: string, power: string) => setSheet((current) => { const selected = current.disciplines[discipline] || []; return { ...current, disciplines: { ...current.disciplines, [discipline]: selected.includes(power) ? selected.filter((item) => item !== power) : [...selected, power] } }; });
  const save = () => { if (name.trim().length < 2) { toast.error("Informe o nome do personagem."); return; } const sheetToSave = appendV5History(sheet, selectedId ? "Ficha V5 atualizada no arquivo." : "Ficha V5 autenticada no arquivo."); setSheet(sheetToSave); const input = { name: name.trim(), concept: concept.trim() || undefined, campaignId: campaignId ? Number(campaignId) : null, sheetData: sheetToSave }; if (selectedId) updateCharacter.mutate({ ...input, characterId: selectedId }); else createCharacter.mutate({ ...input, systemId: "vampiro-v5" }); };
  const addTrait = (kind: "advantages" | "flaws") => { const label = kind === "advantages" ? traitName : flawName; const dots = kind === "advantages" ? traitDots : flawDots; if (!label) return; setSheet((current) => ({ ...current, [kind]: [...current[kind], { name: label, dots }] })); if (kind === "advantages") setTraitName(""); else setFlawName(""); };
  const removeInventoryItem = (itemId: string) => setSheet((current) => ({ ...current, inventory: current.inventory.filter((entry) => entry.id !== itemId), equippedWeaponId: current.equippedWeaponId === itemId ? null : current.equippedWeaponId, equippedArmorId: current.equippedArmorId === itemId ? null : current.equippedArmorId }));
  const equipWeapon = (itemId: string) => setSheet((current) => ({ ...current, equippedWeaponId: current.equippedWeaponId === itemId ? null : itemId }));
  const equipArmor = (itemId: string) => setSheet((current) => ({ ...current, equippedArmorId: current.equippedArmorId === itemId ? null : itemId }));
  const beginInventoryAdd = () => { setEditingInventoryId(null); setInventoryDraft(emptyInventoryDraft()); setInventoryEditorOpen(true); setInventoryOpen(true); };
  const beginInventoryEdit = (item: V5InventoryEntry) => { setEditingInventoryId(item.id); setInventoryDraft({ name: item.name, category: item.category, resources: item.resources, quantity: item.quantity, specification: item.specification, damageText: item.damage === undefined ? "" : String(item.damage), armorText: item.armor === undefined ? "" : String(item.armor) }); setInventoryEditorOpen(true); setInventoryOpen(true); };
  const saveInventoryItem = () => { if (inventoryDraft.name.trim().length < 2) { toast.error("Informe o nome do item."); return; } const existing = inventoryItems.find((item) => item.id === editingInventoryId); const optionalNumber = (value: string) => value.trim() === "" ? undefined : Math.max(0, Number(value) || 0); const item: V5InventoryEntry = { id: existing?.id || `custom-${Date.now().toString(36)}`, catalogId: existing?.catalogId, source: existing?.source || "custom", name: inventoryDraft.name.trim(), category: inventoryDraft.category, resources: Math.max(0, inventoryDraft.resources || 0), quantity: Math.max(1, Math.floor(inventoryDraft.quantity || 1)), damage: optionalNumber(inventoryDraft.damageText), armor: optionalNumber(inventoryDraft.armorText), specification: inventoryDraft.specification.trim() || "Item personalizado registrado no arquivo." }; setSheet((current) => ({ ...current, inventory: existing ? current.inventory.map((entry) => entry.id === existing.id ? item : entry) : [...current.inventory, item], ...reconcileV5EquipmentAfterInventoryEdit(current, item) })); setInventoryEditorOpen(false); setEditingInventoryId(null); toast.success(existing ? "Item do inventário atualizado." : "Item adicionado ao inventário."); };
  const registerExperience = () => { if (!experienceCost) { toast.error("Defina uma evolução com custo maior que zero."); return; } setSheet((current) => ({ ...current, experienceHistory: [...current.experienceHistory, { id: `xp-${Date.now()}`, kind: advancementKind, currentDots, targetDots, cost: experienceCost, recordedAt: Date.now() }] })); toast.success("Evolução adicionada ao histórico da ficha."); };
  const pdfPayload = () => ({ name: name.trim(), concept: concept.trim(), campaignName: selectedCampaignName, sheet });
  const exportPdf = async () => { if (!name.trim()) { toast.error("Informe o nome do personagem antes de exportar."); return; } setIsExporting(true); try { downloadV5Pdf(await createV5PdfFile(pdfPayload())); toast.success("Dossiê PDF preparado para download."); } catch (error) { console.error(error); toast.error("Não foi possível preparar o PDF agora."); } finally { setIsExporting(false); } };
  const sharePdf = async () => { if (!name.trim()) { toast.error("Informe o nome do personagem antes de compartilhar."); return; } setIsSharing(true); try { const result = await shareV5Pdf(pdfPayload()); if (result === "native") toast.success("Escolha o aplicativo, incluindo e-mail ou mensageiro, para enviar o PDF anexado."); else if (result === "unsupported") { downloadV5Pdf(await createV5PdfFile(pdfPayload())); toast.info("Este navegador não compartilha anexos diretamente; o PDF foi baixado."); } } catch (error) { console.error(error); toast.error("Não foi possível abrir o compartilhamento agora."); } finally { setIsSharing(false); } };
  const emailPdf = async () => { if (!name.trim()) { toast.error("Informe o nome do personagem antes de enviar por e-mail."); return; } setIsSharing(true); try { const result = await shareV5Pdf(pdfPayload()); if (result === "native") { toast.success("Selecione seu aplicativo de e-mail para enviar o PDF como anexo."); return; } downloadV5Pdf(await createV5PdfFile(pdfPayload())); window.location.href = createV5MailtoUrl(pdfPayload()); toast.info("Seu navegador não permite anexos no e-mail; o PDF foi baixado para anexar à mensagem aberta."); } catch (error) { console.error(error); toast.error("Não foi possível preparar o e-mail agora."); } finally { setIsSharing(false); } };
  const rollEquippedWeapon = () => { if (!equippedWeapon) { toast.error("Equipe uma arma do inventário antes de rolar o ataque."); return; } const isFirearm = ["pistola", "revolver", "submetralhadora", "rifle", "espingarda", "arco"].includes(equippedWeapon.catalogId || equippedWeapon.id); const pool = Math.max(1, (isFirearm ? sheet.attributes["Destreza"] : sheet.attributes["Força"]) + (isFirearm ? sheet.skills["Armas de Fogo"] : sheet.skills["Armas Brancas"])); const hungerDice = Math.min(pool, Math.max(0, sheet.hunger)); const dice = Array.from({ length: pool }, () => Math.floor(Math.random() * 10) + 1); const successes = dice.filter((die) => die >= 6).length + Math.floor(dice.filter((die) => die === 10).length / 2) * 2; const tens = dice.filter((die) => die === 10).length; const messyCritical = dice.slice(0, hungerDice).includes(10) && tens >= 2; const bestialFailure = dice.slice(0, hungerDice).includes(1) && successes === 0; const verdict = messyCritical ? "Crítico bagunçado" : bestialFailure ? "Falha bestial" : successes > 0 ? "Êxito" : "Falha"; const result = { pool, dice, successes, damage: equippedWeapon.damage ?? 0, hungerDice, verdict, messyCritical, bestialFailure }; setCombatResult(result); if (selectedId) recordRoll.mutate({ systemId: "vampiro-v5", characterId: selectedId, campaignId: campaignId ? Number(campaignId) : null, context: `Ataque com ${equippedWeapon.name}`, resultData: { ...result, weaponId: equippedWeapon.id } }); };
  const performQuickRoll = (option: QuickRollOption) => { const pairs: Record<string, [string, string]> = { briga: ["Força", "Briga"], fogo: ["Destreza", "Armas de Fogo"], furtividade: ["Destreza", "Furtividade"], social: ["Carisma", "Persuasão"], investigacao: ["Inteligência", "Investigação"] }; const [attribute, skill] = pairs[option.id] || ["Raciocínio", "Consciência"]; const pool = Math.max(1, (sheet.attributes[attribute] || 0) + (sheet.skills[skill] || 0)); const dice = Array.from({ length: pool }, () => Math.floor(Math.random() * 10) + 1); const successes = dice.filter((die) => die >= 6).length + Math.floor(dice.filter((die) => die === 10).length / 2) * 2; const result = { label: option.label, pool, dice, successes }; setQuickRollResult(result); if (selectedId) recordRoll.mutate({ systemId: "vampiro-v5", characterId: selectedId, campaignId: campaignId ? Number(campaignId) : null, context: option.label, resultData: { ...result, attribute, skill } }); };

  return <div className="min-h-screen bg-[#101211] text-[#eae3d5]"><div className="mx-auto max-w-7xl px-5 py-8 sm:px-8 lg:px-10"><header className="border-b border-white/10 pb-7"><p className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#83a89a]">Vampiro: A Máscara V5 · ficha 08</p><div className="mt-3 flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><h1 className="font-serif text-5xl leading-none tracking-[-0.04em] text-[#f4eee4]">Sangue, nome<br />e consequência.</h1><p className="mt-4 max-w-2xl text-sm leading-6 text-[#b8b3a8]">Ficha estruturada com clãs, disciplinas, poderes, tipo de predador e estado humano. Os campos abaixo ficam preservados na sua conta do atlas.</p></div><div className="flex max-w-xl flex-wrap items-center gap-2"><SheetSystemSwitcher active="vampiro-v5" /><SystemRuleTooltip systemId="vampiro-v5" /><Button onClick={sharePdf} disabled={isSharing || isExporting} className="h-11 rounded-none border border-[#b55b32]/70 bg-[#b55b32] text-[10px] font-bold uppercase tracking-[0.14em] text-[#161715] hover:bg-[#d27648]"><Share2 className="mr-2 h-4 w-4" /> {isSharing ? "Abrindo compartilhamento" : "Compartilhar PDF"}</Button><Button onClick={emailPdf} disabled={isSharing || isExporting} variant="outline" className="h-11 rounded-none border border-[#83a89a]/60 bg-[#83a89a]/10 text-[10px] font-bold uppercase tracking-[0.14em] text-[#f4eee4] hover:bg-[#83a89a]/20"><Mail className="mr-2 h-4 w-4" /> E-mail</Button><Button onClick={exportPdf} disabled={isExporting || isSharing} variant="outline" className="h-11 rounded-none border border-[#83a89a]/60 bg-transparent text-[10px] font-bold uppercase tracking-[0.14em] text-[#f4eee4] hover:bg-[#83a89a]/20"><Download className="mr-2 h-4 w-4" /> {isExporting ? "Preparando PDF" : "Baixar PDF"}</Button><Link href="/arsenal-v5"><Button className="h-11 rounded-none border border-[#b55b32]/65 bg-[#b55b32]/10 text-[10px] font-bold uppercase tracking-[0.14em] text-[#f4eee4] hover:bg-[#b55b32]/20"><Shield className="mr-2 h-4 w-4" /> Abrir arsenal e compras</Button></Link><p className="basis-full text-[9px] leading-4 text-[#a9c7bb]">Em celular e aplicativos compatíveis, o compartilhamento envia o PDF como anexo. Em navegadores sem esse recurso, o PDF é baixado para anexar ao e-mail.</p></div></div></header>{archiveError ? <div className="mt-5 border border-[#b55b32]/55 bg-[#3b1d19]/60 p-4 text-sm text-[#ffb09d]">Não foi possível consultar as fichas e crônicas preservadas agora. Atualize a página para tentar novamente.</div> : isLoadingArchive ? <div className="mt-5 flex items-center gap-2 border border-[#83a89a]/35 bg-[#171a18] p-4 text-sm text-[#a9c7bb]"><LoaderCircle className="h-4 w-4 animate-spin" /> Consultando fichas e crônicas preservadas…</div> : null}

  <section className="mt-7 grid gap-5 xl:grid-cols-[0.72fr_1.28fr]"><aside className="border border-white/10 bg-[#171a18] p-5"><div className="flex items-center justify-between"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#a9c7bb]">Fichas preservadas</p><Button onClick={newCharacter} variant="outline" size="sm" className="rounded-none border-white/20 text-[#eae3d5]"><Plus className="mr-1 h-4 w-4" /> Nova</Button></div><div className="mt-4 grid gap-2">{vampireCharacters.length ? vampireCharacters.map((character) => <button key={character.id} onClick={() => openCharacter(character)} className={`border p-3 text-left ${selectedId === character.id ? "border-[#b55b32] bg-[#b55b32]/10" : "border-white/10 bg-black/10 hover:border-[#83a89a]/50"}`}><p className="font-serif text-xl text-[#f4eee4]">{character.name}</p><p className="mt-1 text-[9px] font-bold uppercase tracking-[0.13em] text-[#a9c7bb]">{character.concept || "sem conceito"}</p></button>) : <p className="text-sm leading-6 text-[#b8b3a8]">Nenhuma ficha V5 foi autenticada ainda.</p>}</div></aside>
  <main className="space-y-5"><article className="relative overflow-hidden border border-[#b55b32]/45 bg-[#171a18] p-6"><div className="absolute inset-0 dossier-grid opacity-15" /><div className="relative"><div className="grid gap-4 md:grid-cols-3"><label className="flex flex-col gap-2 text-[9px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">Nome<input value={name} onChange={(event) => setName(event.target.value)} className="h-10 border border-white/15 bg-[#101211] px-3 text-sm normal-case tracking-normal text-[#eae3d5]" /></label><label className="flex flex-col gap-2 text-[9px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">Conceito<input value={concept} onChange={(event) => setConcept(event.target.value)} className="h-10 border border-white/15 bg-[#101211] px-3 text-sm normal-case tracking-normal text-[#eae3d5]" /></label><label className="flex flex-col gap-2 text-[9px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">Crônica<select value={campaignId} onChange={(event) => setCampaignId(event.target.value)} className="h-10 border border-white/15 bg-[#101211] px-3 text-sm normal-case tracking-normal text-[#eae3d5]"><option value="">Sem vínculo</option>{campaigns.filter((campaign) => campaign.systemId === "vampiro-v5").map((campaign) => <option key={campaign.id} value={campaign.id}>{campaign.title}</option>)}</select></label></div><div className="mt-5 grid gap-4 md:grid-cols-3"><label className="flex flex-col gap-2 text-[9px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">Clã<select value={sheet.clan} onChange={(event) => chooseClan(event.target.value)} className="h-10 border border-white/15 bg-[#101211] px-3 text-sm normal-case tracking-normal text-[#eae3d5]"><option value="">Escolha uma linhagem</option>{V5_CLANS.map((clan) => <option key={clan.id} value={clan.id}>{clan.name}</option>)}</select></label><label className="flex flex-col gap-2 text-[9px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">Predador<select value={sheet.predator} onChange={(event) => setSheet({ ...sheet, predator: event.target.value })} className="h-10 border border-white/15 bg-[#101211] px-3 text-sm normal-case tracking-normal text-[#eae3d5]"><option value="">Escolha uma abordagem</option>{V5_PREDATORS.map((predator) => <option key={predator.id} value={predator.id}>{predator.name}</option>)}</select></label><label className="flex flex-col gap-2 text-[9px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">Geração<select value={sheet.generation} onChange={(event) => { const item = V5_GENERATIONS.find((entry) => entry.generation === Number(event.target.value)); setSheet({ ...sheet, generation: Number(event.target.value), bloodPotency: item?.bloodPotency ?? 0 }); }} className="h-10 border border-white/15 bg-[#101211] px-3 text-sm normal-case tracking-normal text-[#eae3d5]">{V5_GENERATIONS.map((entry) => <option key={entry.generation} value={entry.generation}>{entry.label}</option>)}</select></label></div>{selectedClan ? <div className="mt-4 border-l border-[#83a89a]/60 pl-4 text-sm leading-6 text-[#c7c1b5]"><p><strong className="font-semibold text-[#f4eee4]">Disciplinas de clã:</strong> {selectedClan.disciplines.join(" · ")}</p><p><strong className="font-semibold text-[#f4eee4]">Perdição:</strong> {selectedClan.bane} <span className="text-[#a9c7bb]">· Compulsão: {selectedClan.compulsion}</span></p></div> : null}{sheet.predator ? <p className="mt-3 text-sm leading-6 text-[#c7c1b5]"><span className="font-semibold text-[#f4eee4]">Bônus do predador:</span> {V5_PREDATORS.find((item) => item.id === sheet.predator)?.bonus}</p> : null}</div></article>

  <section className="border border-[#83a89a]/35 bg-[#171a18] p-5"><div className="flex flex-col justify-between gap-2 sm:flex-row sm:items-end"><div><p className="text-[9px] font-bold uppercase tracking-[0.15em] text-[#83a89a]">Primeiros passos V5</p><h2 className="mt-1 font-serif text-3xl text-[#f4eee4]">Escolha um rumo para a noite.</h2></div><p className="max-w-md text-xs leading-5 text-[#b8b3a8]">Os modelos preenchem atributos e habilidades-base; você pode revisar cada valor antes de salvar. O clã continua definindo suas disciplinas de origem.</p></div><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{V5_STARTER_ARCHETYPES.map((archetype) => <article key={archetype.id} className="border border-white/10 bg-black/10 p-4"><p className="font-serif text-xl text-[#f4eee4]">{archetype.label}</p><p className="mt-1 text-xs leading-5 text-[#b8b3a8]">{archetype.summary}</p><p className="mt-3 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">Afinidades: {archetype.clanHints.map((id) => V5_CLANS.find((clan) => clan.id === id)?.name).join(" · ")}</p><Button onClick={() => applyStarterArchetype(archetype)} variant="outline" size="sm" className="mt-4 h-8 w-full rounded-none border-[#83a89a]/45 text-[9px] font-bold uppercase tracking-[0.12em] text-[#f4eee4] hover:bg-[#83a89a]/15">Aplicar modelo</Button></article>)}</div></section>
  <section className="grid gap-5 lg:grid-cols-3"><article className="border border-white/10 bg-[#171a18] p-5"><div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.16em] text-[#a9c7bb]"><Droplets className="h-4 w-4 text-[#d27648]" /> Marcadores do sangue</div><div className="mt-4 grid gap-4"><label className="flex items-center justify-between gap-3 text-sm">Fome <input type="range" min="0" max="5" value={sheet.hunger} onChange={(event) => setSheet({ ...sheet, hunger: Number(event.target.value) })} className="accent-[#b55b32]" /><strong>{sheet.hunger}/5</strong></label><label className="flex items-center justify-between gap-3 text-sm">Humanidade <input type="range" min="0" max="10" value={sheet.humanity} onChange={(event) => setSheet({ ...sheet, humanity: Number(event.target.value) })} className="accent-[#83a89a]" /><strong>{sheet.humanity}/10</strong></label><div className="border-t border-white/10 pt-3 text-sm leading-6 text-[#c7c1b5]"><p>Potência de Sangue <strong className="text-[#f4eee4]">{sheet.bloodPotency}</strong></p><p>Vitalidade <strong className="text-[#f4eee4]">{health}</strong></p><p>Força de Vontade <strong className="text-[#f4eee4]">{willpower}</strong></p></div></div></article><article className="border border-white/10 bg-[#171a18] p-5 lg:col-span-2"><div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.16em] text-[#a9c7bb]"><UserRound className="h-4 w-4 text-[#d27648]" /> Atributos</div><div className="mt-4 grid gap-4 sm:grid-cols-2 2xl:grid-cols-3">{Object.entries(V5_ATTRIBUTES).map(([group, labels]) => <div key={group}><p className="text-[9px] font-bold uppercase tracking-[0.14em] text-[#d27648]">{group}</p><div className="mt-2 space-y-2">{labels.map((label) => <div key={label} className="flex items-center justify-between border-b border-white/10 py-1 text-sm transition-colors hover:border-[#b55b32]/65"><span className="flex items-center gap-1">{label}<AttributeRuleTooltip systemId="vampiro-v5" attribute={label} /></span><span className="flex items-center gap-2"><button aria-label={`Reduzir ${label}`} onClick={() => updateRating("attributes", label, -1)} className="text-[#a9c7bb]"><ChevronDown className="h-4 w-4" /></button><strong>{sheet.attributes[label]}</strong><button aria-label={`Aumentar ${label}`} onClick={() => updateRating("attributes", label, 1)} className="text-[#d27648]"><ChevronUp className="h-4 w-4" /></button></span></div>)}</div></div>)}</div></article></section>

  <article className="border border-white/10 bg-[#171a18] p-5"><div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.16em] text-[#a9c7bb]"><Sparkles className="h-4 w-4 text-[#d27648]" /> Habilidades</div><div className="mt-4 grid gap-4 md:grid-cols-3">{Object.entries(V5_SKILLS).map(([group, labels]) => <div key={group}><p className="text-[9px] font-bold uppercase tracking-[0.14em] text-[#d27648]">{group}</p><div className="mt-2 space-y-1">{labels.map((label) => <div key={label} className="flex items-center justify-between border-b border-white/10 py-1 text-xs"><span>{label}</span><span className="flex items-center gap-2"><button onClick={() => updateRating("skills", label, -1)} className="text-[#a9c7bb]">−</button><strong>{sheet.skills[label]}</strong><button onClick={() => updateRating("skills", label, 1)} className="text-[#d27648]">+</button></span></div>)}</div></div>)}</div></article>

  <article className="border border-[#83a89a]/40 bg-[#171a18] p-5"><div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.16em] text-[#a9c7bb]"><Crown className="h-4 w-4 text-[#d27648]" /> Disciplinas e poderes</div><div className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{Object.entries(V5_DISCIPLINES).filter(([discipline]) => !selectedClan || selectedClan.disciplines.includes(discipline)).map(([discipline, data]) => <div key={discipline} className="border border-white/10 bg-black/10 p-4"><p className="font-serif text-2xl text-[#f4eee4]">{discipline}</p><p className="mt-1 text-xs leading-5 text-[#b8b3a8]">{data.description}</p><div className="mt-3 space-y-2">{[...data.powers, ...(V5_DISCIPLINE_ADVANCED_POWERS[discipline] || [])].map((power) => <label key={power.name} className="flex cursor-pointer gap-2 text-xs leading-5 text-[#d7d1c4]"><input type="checkbox" checked={(sheet.disciplines[discipline] || []).includes(power.name)} onChange={() => togglePower(discipline, power.name)} className="mt-1 accent-[#b55b32]" /><span><strong>N{power.level} · {power.name}</strong><br />{power.effect}</span></label>)}</div></div>)}</div></article>

  <section className="grid gap-5 lg:grid-cols-2"><article className="archive-paper border border-[#161715]/20 p-5 text-[#161715]"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#b55b32]">Vantagens</p><div className="mt-3 flex gap-2"><select value={traitName} onChange={(event) => setTraitName(event.target.value)} className="h-10 min-w-0 flex-1 border border-[#161715]/20 bg-[#fffaf0] px-2 text-sm"><option value="">Escolha um mérito</option>{V5_ADVANTAGE_DETAILS.map((item) => <option key={item.name} value={item.name}>{item.name} · {item.dots}</option>)}</select><input type="number" min="1" max="5" value={traitDots} onChange={(event) => setTraitDots(Number(event.target.value))} className="h-10 w-14 border border-[#161715]/20 bg-[#fffaf0] px-2" /><Button onClick={() => addTrait("advantages")} className="h-10 rounded-none bg-[#b55b32] text-[#161715]"><Plus className="h-4 w-4" /></Button></div><ul className="mt-4 space-y-2 text-sm">{sheet.advantages.map((item, index) => <li key={`${item.name}-${index}`} className="border-b border-[#161715]/15 pb-1"><div className="flex justify-between"><span>{item.name}</span><strong>{"•".repeat(item.dots)}</strong></div><p className="mt-1 text-xs text-[#5f5a52]">{V5_ADVANTAGE_DETAILS.find((entry) => entry.name === item.name)?.effect}</p></li>)}</ul></article><article className="border border-white/10 bg-[#171a18] p-5"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#ffb08e]">Desvantagens</p><div className="mt-3 flex gap-2"><select value={flawName} onChange={(event) => setFlawName(event.target.value)} className="h-10 min-w-0 flex-1 border border-white/15 bg-[#101211] px-2 text-sm text-[#eae3d5]"><option value="">Escolha uma falha</option>{V5_FLAW_DETAILS.map((item) => <option key={item.name} value={item.name}>{item.name} · {item.dots}</option>)}</select><input type="number" min="1" max="5" value={flawDots} onChange={(event) => setFlawDots(Number(event.target.value))} className="h-10 w-14 border border-white/15 bg-[#101211] px-2 text-[#eae3d5]" /><Button onClick={() => addTrait("flaws")} className="h-10 rounded-none border border-[#b55b32]/60 bg-[#b55b32]/10 text-[#f4eee4]"><Plus className="h-4 w-4" /></Button></div><ul className="mt-4 space-y-2 text-sm text-[#eae3d5]">{sheet.flaws.map((item, index) => <li key={`${item.name}-${index}`} className="border-b border-white/10 pb-1"><div className="flex justify-between"><span>{item.name}</span><strong>{"•".repeat(item.dots)}</strong></div><p className="mt-1 text-xs text-[#b8b3a8]">{V5_FLAW_DETAILS.find((entry) => entry.name === item.name)?.effect}</p></li>)}</ul></article></section>

  <section className="grid gap-5 lg:grid-cols-2"><article className="border border-[#b55b32]/45 bg-[#171a18] p-5"><div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.16em] text-[#a9c7bb]"><BookOpen className="h-4 w-4 text-[#d27648]" /> Calculadora de experiência</div><p className="mt-2 text-sm leading-6 text-[#b8b3a8]">O custo soma cada novo nível adquirido, distinguindo disciplinas de clã e fora de clã.</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><select value={advancementKind} onChange={(event) => setAdvancementKind(event.target.value as V5AdvancementKind)} className="h-10 border border-white/15 bg-[#101211] px-2 text-sm text-[#eae3d5]"><option value="attribute">Atributo · ×5</option><option value="skill">Habilidade · ×3</option><option value="discipline">Disciplina de clã · ×5</option><option value="outOfClanDiscipline">Disciplina externa · ×7</option><option value="bloodPotency">Potência de Sangue · ×10</option></select><input type="number" min="0" max="10" value={currentDots} onChange={(event) => setCurrentDots(Number(event.target.value))} className="h-10 border border-white/15 bg-[#101211] px-3 text-sm text-[#eae3d5]" aria-label="Nível atual" /><input type="number" min={currentDots} max="10" value={targetDots} onChange={(event) => setTargetDots(Number(event.target.value))} className="h-10 border border-white/15 bg-[#101211] px-3 text-sm text-[#eae3d5]" aria-label="Nível desejado" /></div><div className="mt-4 flex flex-wrap items-end justify-between gap-3 border-t border-white/10 pt-4"><span className="text-[10px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">{currentDots} → {targetDots} pontos</span><strong className="font-serif text-4xl text-[#f4eee4]">{experienceCost} <span className="text-base text-[#d27648]">XP</span></strong><Button onClick={registerExperience} disabled={!experienceCost} size="sm" className="h-9 rounded-none border border-[#83a89a]/55 bg-[#83a89a]/10 text-[9px] font-bold uppercase tracking-[0.1em] text-[#f4eee4] hover:bg-[#83a89a]/20"><History className="mr-2 h-3.5 w-3.5" /> Registrar</Button></div>{sheet.experienceHistory.length ? <div className="mt-4 border-t border-white/10 pt-3"><p className="text-[9px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">Histórico de experiência · {sheet.experienceHistory.length} registro(s)</p><div className="mt-2 max-h-24 space-y-1 overflow-y-auto pr-1">{[...sheet.experienceHistory].reverse().map((entry) => <p key={entry.id} className="flex justify-between gap-3 text-xs text-[#c7c1b5]"><span>{getV5AdvancementLabel(entry.kind)} · {entry.currentDots}→{entry.targetDots}</span><strong className="text-[#f4eee4]">{entry.cost} XP</strong></p>)}</div></div> : <p className="mt-4 text-xs text-[#b8b3a8]">Registre evoluções para preservá-las na ficha e no PDF.</p>}</article><Collapsible open={inventoryOpen} onOpenChange={setInventoryOpen}><article className="border border-white/10 bg-[#171a18]"><CollapsibleTrigger asChild><button type="button" className="flex w-full items-center justify-between gap-3 p-5 text-left"><span className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.16em] text-[#a9c7bb]"><Shield className="h-4 w-4 text-[#d27648]" /> Inventário · {inventoryItems.length} item(ns)</span><span className="flex items-center gap-2 text-[9px] font-bold uppercase tracking-[0.12em] text-[#f4eee4]">{inventoryOpen ? "Recolher" : "Gerenciar"}{inventoryOpen ? <ChevronUp className="h-4 w-4 text-[#83a89a]" /> : <ChevronDown className="h-4 w-4 text-[#83a89a]" />}</span></button></CollapsibleTrigger><CollapsibleContent className="border-t border-white/10 px-5 pb-5"><div className="mt-4 grid gap-2 border border-[#83a89a]/35 bg-[#83a89a]/[0.06] p-3 sm:grid-cols-2"><div><p className="flex items-center gap-1 text-[9px] font-bold uppercase tracking-[0.13em] text-[#a9c7bb]"><BadgeCheck className="h-3.5 w-3.5" /> Arma ativa</p><p className="mt-1 font-serif text-lg text-[#f4eee4]">{equippedWeapon?.name || "Nenhuma"}</p></div><div><p className="flex items-center gap-1 text-[9px] font-bold uppercase tracking-[0.13em] text-[#a9c7bb]"><ShieldCheck className="h-3.5 w-3.5" /> Armadura ativa</p><p className="mt-1 font-serif text-lg text-[#f4eee4]">{equippedArmor?.name || "Nenhuma"}</p></div></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3"><p className="text-xs leading-5 text-[#b8b3a8]">Adicione pertences próprios, edite anotações e quantidade, ou remova itens. Salve a ficha para preservar as alterações.</p><Button onClick={beginInventoryAdd} size="sm" className="h-9 rounded-none bg-[#b55b32] text-[9px] font-bold uppercase tracking-[0.12em] text-[#161715] hover:bg-[#d27648]"><PackagePlus className="mr-2 h-4 w-4" /> Adicionar item</Button></div>{inventoryEditorOpen ? <div className="mt-4 border border-[#b55b32]/55 bg-[#101211] p-4"><div className="flex items-center justify-between gap-3"><p className="text-[9px] font-bold uppercase tracking-[0.14em] text-[#ffb08e]">{editingInventoryId ? "Editar item" : "Novo item"}</p><button type="button" onClick={() => setInventoryEditorOpen(false)} className="text-[10px] font-bold uppercase tracking-[0.1em] text-[#a9c7bb]">Cancelar</button></div><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="flex flex-col gap-1 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">Nome<input value={inventoryDraft.name} onChange={(event) => setInventoryDraft((draft) => ({ ...draft, name: event.target.value }))} className="h-9 border border-white/15 bg-[#171a18] px-2 text-sm normal-case tracking-normal text-[#f4eee4]" /></label><label className="flex flex-col gap-1 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">Categoria<select value={inventoryDraft.category} onChange={(event) => setInventoryDraft((draft) => ({ ...draft, category: event.target.value as V5StoreCategory }))} className="h-9 border border-white/15 bg-[#171a18] px-2 text-sm normal-case tracking-normal text-[#f4eee4]">{inventoryCategories.map((category) => <option key={category.value} value={category.value}>{category.label}</option>)}</select></label><label className="flex flex-col gap-1 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">Quantidade<input type="number" min="1" value={inventoryDraft.quantity} onChange={(event) => setInventoryDraft((draft) => ({ ...draft, quantity: Number(event.target.value) }))} className="h-9 border border-white/15 bg-[#171a18] px-2 text-sm text-[#f4eee4]" /></label><label className="flex flex-col gap-1 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">Recursos<input type="number" min="0" max="5" value={inventoryDraft.resources} onChange={(event) => setInventoryDraft((draft) => ({ ...draft, resources: Number(event.target.value) }))} className="h-9 border border-white/15 bg-[#171a18] px-2 text-sm text-[#f4eee4]" /></label><label className="flex flex-col gap-1 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">Dano<input inputMode="numeric" value={inventoryDraft.damageText} onChange={(event) => setInventoryDraft((draft) => ({ ...draft, damageText: event.target.value }))} placeholder="Opcional" className="h-9 border border-white/15 bg-[#171a18] px-2 text-sm normal-case tracking-normal text-[#f4eee4]" /></label><label className="flex flex-col gap-1 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">Proteção<input inputMode="numeric" value={inventoryDraft.armorText} onChange={(event) => setInventoryDraft((draft) => ({ ...draft, armorText: event.target.value }))} placeholder="Opcional" className="h-9 border border-white/15 bg-[#171a18] px-2 text-sm normal-case tracking-normal text-[#f4eee4]" /></label><label className="flex flex-col gap-1 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb] sm:col-span-2">Descrição<textarea value={inventoryDraft.specification} onChange={(event) => setInventoryDraft((draft) => ({ ...draft, specification: event.target.value }))} rows={2} className="border border-white/15 bg-[#171a18] px-2 py-2 text-sm normal-case tracking-normal text-[#f4eee4]" /></label></div><Button onClick={saveInventoryItem} className="mt-4 h-9 rounded-none border border-[#83a89a]/60 bg-[#83a89a]/10 text-[9px] font-bold uppercase tracking-[0.12em] text-[#f4eee4] hover:bg-[#83a89a]/20"><Save className="mr-2 h-3.5 w-3.5" /> {editingInventoryId ? "Atualizar item" : "Adicionar ao inventário"}</Button></div> : null}<div className="mt-4 grid gap-2">{inventoryItems.length ? inventoryItems.map((item) => { const isWeaponEquipped = sheet.equippedWeaponId === item.id; const isArmorEquipped = sheet.equippedArmorId === item.id; const isEquipped = isWeaponEquipped || isArmorEquipped; return <div key={item.id} className={`border p-3 ${isEquipped ? "border-[#83a89a] bg-[#83a89a]/10 shadow-[inset_3px_0_0_#83a89a]" : "border-white/10 bg-black/10"}`}><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><p className="font-serif text-lg text-[#f4eee4]">{item.name}{item.quantity > 1 ? <span className="ml-1 text-sm text-[#a9c7bb]">×{item.quantity}</span> : null}</p>{isEquipped ? <span className="border border-[#83a89a]/60 bg-[#83a89a]/15 px-1.5 py-0.5 text-[8px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">Equipado</span> : null}</div><p className="text-[10px] uppercase tracking-[0.12em] text-[#a9c7bb]">{item.category} · Recursos {item.resources}{item.damage !== undefined ? ` · dano +${item.damage}` : ""}{item.armor !== undefined ? ` · proteção +${item.armor}` : ""}</p><p className="mt-1 text-xs leading-5 text-[#b8b3a8]">{item.specification}</p></div><div className="flex flex-wrap justify-end gap-2">{item.category === "arma" ? <Button onClick={() => equipWeapon(item.id)} aria-pressed={isWeaponEquipped} size="sm" className="h-8 rounded-none border border-[#b55b32]/60 bg-transparent text-[9px] uppercase tracking-[0.1em] text-[#f4eee4] hover:bg-[#b55b32]/15">{isWeaponEquipped ? "Desequipar" : "Equipar"}</Button> : null}{item.category === "armadura" ? <Button onClick={() => equipArmor(item.id)} aria-pressed={isArmorEquipped} size="sm" className="h-8 rounded-none border border-[#83a89a]/60 bg-transparent text-[9px] uppercase tracking-[0.1em] text-[#f4eee4] hover:bg-[#83a89a]/15">{isArmorEquipped ? "Desequipar" : "Equipar"}</Button> : null}<Button onClick={() => beginInventoryEdit(item)} size="icon" variant="outline" aria-label={`Editar ${item.name}`} className="h-8 w-8 rounded-none border-white/15 text-[#a9c7bb]"><Pencil className="h-3.5 w-3.5" /></Button><Button onClick={() => removeInventoryItem(item.id)} size="icon" variant="outline" aria-label={`Remover ${item.name}`} className="h-8 w-8 rounded-none border-white/15 text-[#ffb08e]"><Trash2 className="h-3.5 w-3.5" /></Button></div></div></div>; }) : <p className="text-sm leading-6 text-[#b8b3a8]">Nenhum item registrado. Use a Casa de Recursos ou adicione um item próprio.</p>}</div>{equippedWeapon ? <div className="mt-4 border-t border-white/10 pt-4"><div className="flex items-center justify-between gap-3"><div><p className="text-[9px] font-bold uppercase tracking-[0.14em] text-[#d27648]">Equipada · {equippedWeapon.name}</p><p className="mt-1 text-xs text-[#c7c1b5]">Ataque usa { ["pistola", "revolver", "submetralhadora", "rifle", "espingarda", "arco"].includes(equippedWeapon.catalogId || equippedWeapon.id) ? "Destreza + Armas de Fogo" : "Força + Armas Brancas" } · dano +{equippedWeapon.damage ?? 0}</p></div><Button onClick={rollEquippedWeapon} className="h-10 rounded-none bg-[#b55b32] text-[10px] font-bold uppercase tracking-[0.12em] text-[#161715] hover:bg-[#d27648]"><Dice6 className="mr-2 h-4 w-4" /> Rolar</Button></div>{combatResult ? <div className="mt-3 border border-[#83a89a]/45 bg-[#101211] p-3 text-sm"><p className="text-[#a9c7bb]">Reserva {combatResult.pool} · sucessos {combatResult.successes} · dano final +{combatResult.damage}</p><p className="mt-2 font-mono text-xs tracking-[0.18em] text-[#f4eee4]">{combatResult.dice.join(" · ")}</p></div> : null}</div> : null}</CollapsibleContent></article></Collapsible></section>

  {combatResult ? <article className="border border-[#83a89a]/45 bg-[#101211] p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-[9px] font-bold uppercase tracking-[0.15em] text-[#a9c7bb]">Registro de ataque · arma equipada</p><p className="mt-2 font-serif text-3xl text-[#f4eee4]">{combatResult.verdict}</p><p className="mt-1 text-sm text-[#c7c1b5]">Reserva {combatResult.pool} · {combatResult.hungerDice} dado(s) de Fome · {combatResult.successes} êxito(s) · dano +{combatResult.damage}</p></div><span className="border border-[#b55b32]/60 px-3 py-2 text-[9px] font-bold uppercase tracking-[0.12em] text-[#ffb08e]">{selectedId ? "Preservado na memória" : "Não autenticado"}</span></div><div className="mt-4 flex flex-wrap gap-2">{combatResult.dice.map((die, index) => <span key={`${die}-${index}`} className={`animate-dice-tumble grid h-9 w-9 place-items-center border font-mono text-sm font-bold ${index < combatResult.hungerDice ? "border-[#b55b32] bg-[#b55b32]/20 text-[#ffb08e]" : "border-[#83a89a]/60 bg-[#17211d] text-[#f4eee4]"}`}>{die}</span>)}</div>{combatResult.messyCritical || combatResult.bestialFailure ? <p className="mt-3 text-sm text-[#ffb08e]">A Besta marcou esta rolagem: {combatResult.messyCritical ? "crítico bagunçado" : "falha bestial"}.</p> : null}</article> : null}
  <SheetCreationGuide system="Vampiro: A Máscara V5" intro="A ficha é construída por escolhas narrativas e pontos. Os modelos são atalhos opcionais: adapte cada decisão ao conceito e à crônica." steps={["Defina nome, conceito e a crônica. Escolha um clã para preparar as disciplinas de origem.", "Aplique um modelo inicial ou distribua atributos e habilidades manualmente.", "Escolha um predador, vantagens, falhas e poderes. Salve a ficha para preservar o dossiê."]} />
  <CustomArchetypePanel systemId="vampiro-v5" snapshot={{ clan: sheet.clan, predator: sheet.predator, attributes: sheet.attributes, skills: sheet.skills, disciplines: sheet.disciplines }} onApply={applyCustomArchetype} />
  <QuickRollPanel title="Rolagens rápidas V5" intro="Atalhos para cenas frequentes. A ficha registra a rolagem quando um personagem preservado estiver aberto." options={[{ id: "briga", label: "Briga", detail: "Força + Briga" }, { id: "fogo", label: "Armas de fogo", detail: "Destreza + Armas de Fogo" }, { id: "furtividade", label: "Furtividade", detail: "Destreza + Furtividade" }, { id: "social", label: "Persuasão", detail: "Carisma + Persuasão" }, { id: "investigacao", label: "Investigação", detail: "Inteligência + Investigação" }]} onRoll={performQuickRoll} />
  {quickRollResult ? <article className="border border-[#83a89a]/45 bg-[#101211] p-4"><p className="text-[9px] font-bold uppercase tracking-[0.14em] text-[#a9c7bb]">{quickRollResult.label} · reserva {quickRollResult.pool} · {quickRollResult.successes} êxito(s)</p><p className="mt-2 font-mono text-xs tracking-[0.18em] text-[#f4eee4]">{quickRollResult.dice.join(" · ")}</p></article> : null}
  <article className="border border-white/10 bg-[#171a18] p-5"><div className="flex items-center justify-between gap-3"><div><p className="text-[9px] font-bold uppercase tracking-[0.15em] text-[#a9c7bb]">Histórico compacto da ficha</p><p className="mt-1 text-xs leading-5 text-[#b8b3a8]">As últimas escolhas e salvamentos ficam preservados neste dossiê.</p></div><span className="border border-[#83a89a]/35 px-2 py-1 text-[9px] font-bold uppercase tracking-[0.12em] text-[#a9c7bb]">{sheet.history.length}/8</span></div>{sheet.history.length ? <ol className="mt-4 grid gap-2 sm:grid-cols-2">{sheet.history.map((entry) => <li key={entry.id} className="border-l-2 border-[#83a89a]/55 bg-black/10 px-3 py-2 text-xs text-[#d8d2c6]"><span className="block text-[9px] font-bold uppercase tracking-[0.1em] text-[#a9c7bb]">{new Date(entry.recordedAt).toLocaleString("pt-BR", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</span>{entry.label}</li>)}</ol> : <p className="mt-4 text-sm text-[#b8b3a8]">Escolha um clã, aplique um modelo ou salve a ficha para iniciar o histórico.</p>}</article>
  <div className="flex flex-col justify-between gap-3 border-t border-white/10 pt-6 sm:flex-row sm:items-center"><p className={`flex items-center gap-2 text-xs ${isSavingSheet ? "text-[#a9c7bb]" : lastSavedAt ? "text-[#9dccb8]" : "text-[#b8b3a8]"}`}>{isSavingSheet ? <><LoaderCircle className="h-4 w-4 animate-spin" /> Gravando alterações no arquivo…</> : lastSavedAt ? <><CheckCircle2 className="h-4 w-4" /> Salvo com sucesso às {lastSavedAt.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}.</> : "As alterações serão preservadas quando você salvar."}</p><Button onClick={save} disabled={isSavingSheet} className="h-12 rounded-none bg-[#b55b32] px-6 text-[10px] font-bold uppercase tracking-[0.16em] text-[#161715] hover:bg-[#d27648]">{isSavingSheet ? <LoaderCircle className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />} {isSavingSheet ? "Salvando" : selectedId ? "Salvar ficha V5" : "Autenticar ficha V5"}</Button></div></main></section></div></div>;
}

export default function VampireSheet() { return <DashboardLayout><V5SheetContent /></DashboardLayout>; }
